CREATE TYPE "AccountType" AS ENUM ('BANK','CASH','SAVINGS');
CREATE TYPE "TransactionType" AS ENUM ('INCOME','EXPENSE','TRANSFER_IN','TRANSFER_OUT');
CREATE TYPE "ImportStatus" AS ENUM ('PREVIEW','COMMITTED','FAILED');
CREATE TABLE "User" ("id" TEXT PRIMARY KEY,"email" TEXT NOT NULL UNIQUE,"name" TEXT NOT NULL,"password" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "Session" ("id" TEXT PRIMARY KEY,"userId" TEXT NOT NULL,"csrfToken" TEXT NOT NULL UNIQUE,"expiresAt" TIMESTAMP(3) NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "Session_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE);
CREATE TABLE "Account" ("id" TEXT PRIMARY KEY,"userId" TEXT NOT NULL,"name" TEXT NOT NULL,"type" "AccountType" NOT NULL,"currency" CHAR(3) NOT NULL DEFAULT 'PLN',"openingBalance" DECIMAL(19,2) NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,"archivedAt" TIMESTAMP(3),CONSTRAINT "Account_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE);
CREATE TABLE "Category" ("id" TEXT PRIMARY KEY,"userId" TEXT NOT NULL,"name" TEXT NOT NULL,"color" TEXT NOT NULL,"icon" TEXT NOT NULL,"isIncome" BOOLEAN NOT NULL DEFAULT false,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "Category_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE);
CREATE TABLE "ImportBatch" ("id" TEXT PRIMARY KEY,"userId" TEXT NOT NULL,"accountId" TEXT NOT NULL,"filename" TEXT NOT NULL,"status" "ImportStatus" NOT NULL DEFAULT 'PREVIEW',"importedCount" INTEGER NOT NULL DEFAULT 0,"skippedCount" INTEGER NOT NULL DEFAULT 0,"errorCount" INTEGER NOT NULL DEFAULT 0,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"committedAt" TIMESTAMP(3),CONSTRAINT "ImportBatch_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE);
CREATE TABLE "Transaction" ("id" TEXT PRIMARY KEY,"userId" TEXT NOT NULL,"accountId" TEXT NOT NULL,"categoryId" TEXT,"type" "TransactionType" NOT NULL,"amount" DECIMAL(19,2) NOT NULL,"description" TEXT NOT NULL,"bookedAt" DATE NOT NULL,"transferGroupId" TEXT,"importBatchId" TEXT,"fingerprint" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Transaction_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE,CONSTRAINT "Transaction_accountId_fkey" FOREIGN KEY ("accountId") REFERENCES "Account"("id") ON DELETE RESTRICT,CONSTRAINT "Transaction_categoryId_fkey" FOREIGN KEY ("categoryId") REFERENCES "Category"("id") ON DELETE SET NULL,CONSTRAINT "Transaction_importBatchId_fkey" FOREIGN KEY ("importBatchId") REFERENCES "ImportBatch"("id") ON DELETE SET NULL);
CREATE TABLE "Budget" ("id" TEXT PRIMARY KEY,"userId" TEXT NOT NULL,"categoryId" TEXT NOT NULL,"month" DATE NOT NULL,"limit" DECIMAL(19,2) NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Budget_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE,CONSTRAINT "Budget_categoryId_fkey" FOREIGN KEY ("categoryId") REFERENCES "Category"("id") ON DELETE CASCADE);
CREATE TABLE "CategorizationRule" ("id" TEXT PRIMARY KEY,"userId" TEXT NOT NULL,"phrase" TEXT NOT NULL,"categoryId" TEXT NOT NULL,"priority" INTEGER NOT NULL DEFAULT 100,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "CategorizationRule_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE,CONSTRAINT "CategorizationRule_categoryId_fkey" FOREIGN KEY ("categoryId") REFERENCES "Category"("id") ON DELETE CASCADE);
CREATE UNIQUE INDEX "Account_userId_name_key" ON "Account"("userId","name"); CREATE INDEX "Account_userId_archivedAt_idx" ON "Account"("userId","archivedAt");
CREATE UNIQUE INDEX "Category_userId_name_isIncome_key" ON "Category"("userId","name","isIncome"); CREATE INDEX "Category_userId_idx" ON "Category"("userId");
CREATE UNIQUE INDEX "Transaction_userId_fingerprint_key" ON "Transaction"("userId","fingerprint"); CREATE INDEX "Transaction_userId_bookedAt_idx" ON "Transaction"("userId","bookedAt" DESC); CREATE INDEX "Transaction_accountId_bookedAt_idx" ON "Transaction"("accountId","bookedAt"); CREATE INDEX "Transaction_userId_categoryId_bookedAt_idx" ON "Transaction"("userId","categoryId","bookedAt"); CREATE INDEX "Transaction_transferGroupId_idx" ON "Transaction"("transferGroupId");
CREATE UNIQUE INDEX "Budget_userId_categoryId_month_key" ON "Budget"("userId","categoryId","month"); CREATE INDEX "Budget_userId_month_idx" ON "Budget"("userId","month");
CREATE INDEX "Session_userId_idx" ON "Session"("userId"); CREATE INDEX "Session_expiresAt_idx" ON "Session"("expiresAt"); CREATE INDEX "ImportBatch_userId_createdAt_idx" ON "ImportBatch"("userId","createdAt" DESC); CREATE UNIQUE INDEX "CategorizationRule_userId_phrase_key" ON "CategorizationRule"("userId","phrase"); CREATE INDEX "CategorizationRule_userId_priority_idx" ON "CategorizationRule"("userId","priority");
